INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "高从诲", "aliases": ["高從誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光三年条所见人物：高从诲。", "biography": null, "status": "draft", "id": "361de308-8df0-56e4-ac98-81f6b9297e26"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}, {"name": "尹实", "aliases": ["尹實"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉郢州刺史。947年高从诲攻郢州时将其击败。《旧五代史》高从诲传也记这场战事，写高从诲攻城旬日后败退。生卒年未载。", "biography": null, "status": "draft", "id": "7bbd81b7-2cd4-58b9-80da-3e8e1064126f"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "高季昌", "aliases": ["高季兴"], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“高季昌受命为荆南节度使”中为受任者。", "biography": null, "status": "draft", "id": "e1d9e2c4-6e41-5d7c-8d65-eb79a2407418"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘弘弼", "aliases": ["劉弘弼", "刘洪弼", "劉洪弼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘弼，获封王爵之子。", "biography": null, "status": "draft", "id": "dcf1aa4f-270b-5fb0-bf60-4a3911672aad"}, {"name": "刘弘道", "aliases": ["劉弘道", "刘洪道", "劉洪道"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘道，获封王爵之子。", "biography": null, "status": "draft", "id": "2791eee3-070c-5eaa-aff3-0150a373e3f8"}, {"name": "刘弘益", "aliases": ["劉弘益", "刘洪益", "劉洪益"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘益，获封王爵之子。", "biography": null, "status": "draft", "id": "b6ba5da7-7dfb-528d-ab64-38b347820515"}, {"name": "刘弘济", "aliases": ["劉弘济", "刘洪濟", "劉洪濟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘济，获封王爵之子。", "biography": null, "status": "draft", "id": "828b2644-f967-5a95-a711-a0cc40ea3aac"}, {"name": "刘弘简", "aliases": ["劉弘简", "刘洪簡", "劉洪簡"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘简，获封王爵之子。", "biography": null, "status": "draft", "id": "5814e49d-b7ee-5436-b6db-991b13d57752"}, {"name": "刘弘建", "aliases": ["劉弘建", "刘洪建", "劉洪建"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘建，获封王爵之子。", "biography": null, "status": "draft", "id": "a4ee307a-f834-51b9-be88-ac7b7260fdc8"}, {"name": "刘弘暐", "aliases": ["劉弘暐", "刘洪暐", "劉洪暐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘暐，获封王爵之子。", "biography": null, "status": "draft", "id": "9f597d6b-5256-5e1f-8974-19174d11ed19"}, {"name": "刘弘昭", "aliases": ["劉弘昭", "刘洪昭", "劉洪昭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘昭，获封王爵之子。", "biography": null, "status": "draft", "id": "89372e0e-da93-5c5b-adc0-a8710c161727"}, {"name": "窦贞固", "aliases": ["竇貞固"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：窦贞固，原节度推官、获任者。", "biography": null, "status": "draft", "id": "628caf07-3ba2-5bc4-8630-598667f5bdd0"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "李涛（后晋宋初官员）", "aliases": ["李濤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李澣的兄长，后晋至宋初官员。《宋史》记他宋初任兵部尚书，去世时六十四岁，年代与887年已在杨行密军中的同名李涛不相容，本批单独建档。生卒年不凭年龄反推，后续旧库记录需逐条核对。", "biography": null, "status": "draft", "id": "c03574d2-e4e9-5739-be38-c52f0c0de233"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}, {"name": "刘承训", "aliases": ["劉承訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的儿子。947年九月刘知远诏赴澶、魏劳军时，任命他为东京留守。生卒年尚未录入。", "biography": null, "status": "draft", "id": "4e08b6fa-2adc-5da7-b83b-0448f2cda108"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "和凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：和凝，翰林学士、建议者。", "biography": null, "status": "draft", "id": "f4084e8d-6018-5318-8498-525d067ebeda"}, {"name": "赵匡赞", "aliases": ["趙匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵延寿的儿子。947年正月受耶律德光任命为护国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "ad59529e-c641-5bb7-bde5-3749239fd1d3"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

